logic:
element.style.position = 'relative';

var existing = element.parentElement.querySelector('.contact-support-button-inline');
if (existing) {
  return;
}

var btn = document.createElement('a');
btn.href = '/hc/en-us/requests/new';
btn.className = 'contact-support-button-inline';
btn.textContent = 'Contact Support to turn on a feature';
btn.style.display = 'block';
btn.style.marginTop = '12px';
btn.style.padding = '10px 20px';
btn.style.backgroundColor = '#0072e3';
btn.style.color = '#ffffff';
btn.style.textDecoration = 'none';
btn.style.borderRadius = '6px';
btn.style.fontWeight = '600';
btn.style.fontSize = '15px';
btn.style.textAlign = 'center';
btn.style.maxWidth = '400px';
btn.style.transition = 'background-color 0.2s';

btn.addEventListener('mouseenter', function() {
  btn.style.backgroundColor = '#005bb5';
});
btn.addEventListener('mouseleave', function() {
  btn.style.backgroundColor = '#0072e3';
});

element.parentElement.insertBefore(btn, element.nextSibling);
